update public.content_blocks
set text='בטופס הבקשה לשיחה חוזרת אנו מבקשים שם, מספר טלפון, יעד שמעניין אתכם ואישור למדיניות זו. כתובת דוא״ל היא שדה רשות. הפרטים נמסרים מרצונכם ונשלחים באמצעות שרת האתר כהודעת דוא״ל לתיבת העסק בשירות Gmail של Google, לצורך חזרה אליכם ומענה לפנייה. הטופס אינו יוצר רשומת פנייה במסד הנתונים של האתר ואינו שומר קובץ פניות בשרת. ההודעה נשמרת בתיבת הדוא״ל של העסק והגישה אליה מוגבלת לצוות המורשה. בדיקות תקינות ומניעת שימוש לרעה מתבצעות בזמן הטיפול בבקשה; מזהים טכניים שעברו גיבוב נשמרים לזמן קצר בזיכרון השרת בלבד. שליחת הטופס אינה הרשמה לדיוור שיווקי. לבקשות לעיון, תיקון או מחיקת הודעה אפשר לפנות אלינו בכתובת roniellatours@gmail.com. פנייה בוואטסאפ או ביקור בפייסבוק וב־YouTube כפופים גם למדיניות הפרטיות של אותן פלטפורמות.'
